import { getDashboardData } from './data'

export async function CardStats() {
  const { totalRevenue, totalInvoices } = await getDashboardData()

  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card">
        <h2>Total Revenue</h2>
        <p>${totalRevenue.toLocaleString()}</p>
      </div>
      <div className="card">
        <h2>Total Invoices</h2>
        <p>{totalInvoices}</p>
      </div>
    </div>
  )
}

export function CardStatsSkeleton() {
  return (
    <div className="grid grid-cols-2 gap-4">
      <div className="card skeleton">
        <h2>Total Revenue</h2>
        <p>&nbsp;</p>
      </div>
      <div className="card skeleton">
        <h2>Total Invoices</h2>
        <p>&nbsp;</p>
      </div>
    </div>
  )
}

